import{_ as s,C as e,o as i,c as o,E as a,a2 as n}from"./chunks/framework.BdWD-ld-.js";const b=JSON.parse('{"title":"字符串“假”，为什么拿到了完成进度？","description":"","frontmatter":{"title":"字符串“假”，为什么拿到了完成进度？","article_type":"experiment-report","edition":"research-center","research_question":"工具结果变成完成证据时，布尔类型由谁检查？","summary":"八组隔离输入揭示一个文档解析器的真值转换边界；严格裁判合同提供的是另一接口的对照，而不是系统可靠性排名。","sources":"同日核验的解析器文档、裁判合同与内部实验记录","date":"2026-11-18","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261118-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-18-sig-20261118-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-18-sig-20261118-006.md","filePath":"zh/industry/2026-11-18-sig-20261118-006.md","lastUpdated":1795004020000}'),l={name:"zh/industry/2026-11-18-sig-20261118-006.md"};function h(c,t,p,u,g,k){const d=e("ArticleCover"),r=e("ArticleTableScroll");return i(),o("div",null,[a(d,{image:"/assets/covers/daily-2026-11-18-sig-20261118-006-cover.png",kicker:"研究成果",title:"字符串“假”，为什么拿到了完成进度？",summary:"八组隔离输入揭示一个文档解析器的真值转换边界；严格裁判合同提供的是另一接口的对照，而不是系统可靠性排名。",version:"2026-11-18",languageHref:"/en/industry/2026-11-18-sig-20261118-006",languageLabel:"English"}),a(r,{language:"zh"}),t[0]||(t[0]=n('<h1 id="字符串-假-为什么拿到了完成进度" tabindex="-1">字符串“假”，为什么拿到了完成进度？ <a class="header-anchor" href="#字符串-假-为什么拿到了完成进度" aria-label="Permalink to &quot;字符串“假”，为什么拿到了完成进度？&quot;">​</a></h1><p>把“没有找到”写成字符串，可能得到与布尔假完全不同的进度。在本次隔离探针中，同一个文档示例把字符串 <code>&quot;false&quot;</code> 计为“记录已读”，却把布尔值 <code>false</code>（布尔假）留在部分完成。问题落在工具结果变成证据的那一刻：<strong>真值转换不能代替类型合同</strong>。工具适配器作者可以据此检查，究竟哪一层承诺了字段类型，哪一层负责拒绝异常值。</p><h2 id="一次转换-改变了字段的含义" tabindex="-1">一次转换，改变了字段的含义 <a class="header-anchor" href="#一次转换-改变了字段的含义" aria-label="Permalink to &quot;一次转换，改变了字段的含义&quot;">​</a></h2><p>MedHarnessBench（医疗智能体过程评测基准）的当前运行器文档提供了读取结果解析示例。这个例子的职责很具体：接收工具事件中的查询结果，再把它转换为可以汇总的进度。字段类型在此处是否已经可靠，决定了这一步转换的业务含义。</p><p>示例中的 <code>resolve_read</code>（读取结果解析函数）从事件取出 <code>found</code>（是否找到字段），先做 Python（本次执行所用编程语言）的真值转换，再决定是否增加已读里程碑。</p><p>代码把这个里程碑命名为 <code>record_read</code>（记录已读里程碑）。关键表达式如下，属于公开文档的原字段节选：<a href="https://raw.githubusercontent.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/main/runner/README.md" target="_blank" rel="noreferrer">运行器文档</a>。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">found </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((event.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">or</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}).get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;found&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>这个表达式询问的是值在该语言中是否为真，并没有先询问它是不是布尔值。非空字符串即使拼写为“假”，仍会转成真；整数一也一样。只有当上游已经保证字段类型时，二者才可能在这个接口上等价。这是接口前提，不能从函数名或“解析成功”反推出来。</p><p>论文把模型提议、环境产生的效果与评估判断分开，是有意义的责任划分。但这种高层划分不能替代每个转换点的输入前提。<a href="https://arxiv.org/html/2610.15714v1" target="_blank" rel="noreferrer">论文第一版第 3.2 节</a>所定义的过程评测，也不能单凭一个辅助示例就被判定失效。</p><h2 id="八组输入只回答示例层的问题" tabindex="-1">八组输入只回答示例层的问题 <a class="header-anchor" href="#八组输入只回答示例层的问题" aria-label="Permalink to &quot;八组输入只回答示例层的问题&quot;">​</a></h2><p>同日 Analysis（研究分析阶段）已经执行了内部实验：从已读文档用抽象语法树抽出未改动的函数，输入八组人工构造结果。没有导入上游运行器，没有调用模型或医疗环境。下表转述该实验实际输出；右栏是我们提出的严格布尔对照策略，<strong>不是上游实现</strong>。</p><table tabindex="0"><thead><tr><th>输入字段值</th><th>文档函数的输出</th><th>我们提出的严格布尔对照</th></tr></thead><tbody><tr><td>布尔 <code>true</code>（布尔真）</td><td>成功，增加记录已读</td><td>成功</td></tr><tr><td>布尔 <code>false</code></td><td>部分完成，不增加</td><td>部分完成</td></tr><tr><td><code>null</code>（空值）</td><td>部分完成，不增加</td><td>类型无效</td></tr><tr><td>字符串 <code>&quot;false&quot;</code></td><td>成功，增加记录已读</td><td>类型无效</td></tr><tr><td>字符串 <code>&quot;true&quot;</code></td><td>成功，增加记录已读</td><td>类型无效</td></tr><tr><td>整数 <code>0</code></td><td>部分完成，不增加</td><td>类型无效</td></tr><tr><td>整数 <code>1</code></td><td>成功，增加记录已读</td><td>类型无效</td></tr><tr><td>空列表 <code>[]</code></td><td>部分完成，不增加</td><td>类型无效</td></tr></tbody></table><p>来源：本日内部隔离实验；方法、原输入和输出见随文<a href="/joinwell52/assets/evidence/2026-11-18-sig-20261118-006/experiment-006.json">实验记录</a>及<a href="/joinwell52/assets/evidence/2026-11-18-sig-20261118-006/resolver-probe.zip">可复查实验程序</a>。附带程序保留同一解析函数与八组对照，供读者复查，本篇生产阶段没有重新执行实验。八个输入不是八个临床任务，也不是八次完整基准运行。</p><p>实验否定了一个很窄的假设：“这个示例只有遇到布尔真才增加进度。”它没有说明非布尔值能通过原生生产者、适配器派发和最终汇总。假如工具的序列化合同已强制布尔类型，字符串输入可能根本到不了这里；此时探针展示的是防御性边界，而不是可达故障。</p><h2 id="严格裁判合同管的是另一个接口" tabindex="-1">严格裁判合同管的是另一个接口 <a class="header-anchor" href="#严格裁判合同管的是另一个接口" aria-label="Permalink to &quot;严格裁判合同管的是另一个接口&quot;">​</a></h2><p>chi-Bench（医疗任务环境评测基准）的当前裁判文档明确要求 JSON（结构化数据交换格式）布尔值；字符串形式的假不会被解释为通过。它还检查完整的裁判条目身份、证据引用和输出完整性。裁判超时、缺失或不完整会使测量无效；传输中的数值零只是占位，不能直接解释为智能体拿到零分。<a href="https://raw.githubusercontent.com/actava-ai/chi-bench/main/docs/judge.md" target="_blank" rel="noreferrer">裁判合同</a></p><p>两份材料来自不同作者团队，但它们没有独立复现同一个系统。前者位于工具事件到进度的转换点；后者位于裁判输出到有效测量的接纳点。比较的价值在于看清责任位置，不能据此排出两个基准的可靠性高下，更不能断言后者所有工具结果都受到相同类型约束。</p><p>对于读者自己的适配器，一条可执行的检查链是：</p><table tabindex="0"><thead><tr><th>环节</th><th>负责者与输入</th><th>必须留下的结果</th><th>停止条件</th></tr></thead><tbody><tr><td>产生工具结果</td><td>工具实现提供原始字段</td><td>明确且版本化的字段类型约定</td><td>类型约定缺失，先记为未知</td></tr><tr><td>接纳并解析</td><td>适配器接收原始值</td><td>合法值、业务否定、无效测量分开</td><td>类型不符或字段缺失，按声明策略处理</td></tr><tr><td>增加进度</td><td>进度聚合器读取已接纳结果</td><td>能追溯到原结果的里程碑</td><td>不以非空、可解析或真值替代业务成功</td></tr><tr><td>形成评测</td><td>评估器接收完整证据</td><td>有效结果及无效原因</td><td>所需裁判缺失时不冒充有效失败</td></tr></tbody></table><p>这张表是我们的检查建议，并非两套系统已统一实现的流程。以字符串假为贯穿例子：生产者若不能证明只会输出布尔值，适配器就应明确承担拒绝或标记无效的责任；聚合器随后只能消费有身份、有语义的结果。修复点在哪里，应由真实调用链决定。</p><h2 id="仍缺的是原生路径证据" tabindex="-1">仍缺的是原生路径证据 <a class="header-anchor" href="#仍缺的是原生路径证据" aria-label="Permalink to &quot;仍缺的是原生路径证据&quot;">​</a></h2><p>本篇的公开事实来自两个项目各自的文档；这些是可核验的一手定义，不是独立运行验证。内部实验只支持所抽取函数的行为。我们的解释是应在生产者与消费者之间分配类型检查责任，尚未观察到临床影响、总体成功率失真或原生路径漏洞。文档快照于 2026-11-18 的 Reading（深度阅读阶段）获取并按字节固定；可变分支没有被伪装成论文运行时的固定提交。</p><p>下一步应核对原生生产者模式，保留从字段生成、接纳、解析到最终汇总的同次调用证据，再测试错误类型是否实际可达。如果上游始终拒绝这些输入，就应把结论停在示例的健壮性边界；如果它们能进入汇总，还需要量出哪些里程碑和最终结果受到影响。<strong>能区分布尔假与无效测量，是检查的起点；整个系统是否已经做到，仍需另一层证据。</strong></p>',23))])}const _=s(l,[["render",h]]);export{b as __pageData,_ as default};
